import random
from taskdag.scheduler import Scheduler

random.seed(1234)
def descendants(s, name):
    """All tasks transitively depending on name (following dependent edges)."""
    dependents = {n: set() for n in s.tasks()}
    for t in s.tasks():
        for dep in s._deps[t]:
            dependents[dep].add(t)
    out, stack = set(), list(dependents[name])
    while stack:
        cur = stack.pop()
        if cur not in out:
            out.add(cur)
            stack.extend(dependents[cur])
    return out

ok = 0
for trial in range(300):
    names = [chr(ord('a') + i) for i in range(random.randint(1, 9))]
    random.shuffle(names)
    s = Scheduler()
    # Build a random DAG: each name (in shuffled order) may depend on earlier ones.
    for i, n in enumerate(names):
        s.add_task(n)
        for prev in names[:i]:
            if random.random() < 0.25:
                s.add_dependency(n, prev)
    fails = {n for n in s.tasks() if random.random() < 0.15}
    if not fails:
        continue
    calls = []
    def runner(name):
        calls.append(name)
        if name in fails:
            raise RuntimeError("boom")
    status = s.run(runner)
    # Invariant 1: full map, every task one of the three statuses.
    assert set(status) == set(s.tasks())
    assert all(v in ("ok", "failed", "skipped") for v in status.values())
    # Invariant 2: runner called exactly for ok+failed, never skipped; in topo order.
    assert set(calls) == {n for n, v in status.items() if v in ("ok", "failed")}
    assert calls == [n for n in s.topo_order() if n in calls]
    # Invariant 3: 'failed' exactly the set whose runner raised.
    assert status[fails.pop() if False else next(iter(fails))]  # (noop sanity)
    assert {n for n, v in status.items() if v == "failed"} == fails
    # Invariant 4: transitive skip -- any task that depends (directly or
    # transitively) on a failed task must be 'skipped' and never run.
    blocked = set()
    for f in fails:
        blocked |= descendants(s, f)
    for n in blocked:
        assert status[n] == "skipped", (n, status[n])
        assert n not in calls
    # Invariant 5: no task is both blocked and reported ok; every 'skipped'
    # task is blocked, and tasks not blocked keep their natural ok/failed.
    assert set(status) - blocked == {n for n, v in status.items() if v != "skipped"}
    ok += 1
print(f"random sweep: {ok} failing-graph trials, all invariants held")
